import pathlib,os,stat,fcntl,time,hashlib,json,subprocess,signal,sys
R=pathlib.Path('/home/charl/Moriarty/.moriarty-dev/runtime/sherlock-review-20261017')
D=R/'native-p12-actual-host-provision-20261019'
M=D/'actual-reversible-maintenance-01';M.mkdir(mode=0o700)
host=pathlib.Path('/home/charl/.cargo/registry/index/index.crates.io-1949cf8c6b5b557f/.cache/ca/mi/camino')
recovered=R/'native06-p9-recovered-exact-camino-index-20261019/camino';backup=M/'camino.current-20024.backup'
newsha='389cca5bb2d96f8e8bdd725016a519b4dce18254547cbe2272a6732034650db9';oldsha='25283ab3e91ccf81d4d08a4e6346df3a273bf23fbd944911bc6bb2a851d24cba'
G=pathlib.Path('/sys/fs/cgroup/moriarty-sherlock-ledger9-20261018-06');source=pathlib.Path('/home/charl/Moriarty/.moriarty-dev/runtime/sherlock-sdk-compile-20261018-06/source-home')
fds=[];identities=[];original=None;armed=False;replaced=False
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def st(p):
 s=os.lstat(p);return dict(device=s.st_dev,inode=s.st_ino,mode=s.st_mode,uid=s.st_uid,gid=s.st_gid,links=s.st_nlink,size=s.st_size,atime_ns=s.st_atime_ns,mtime_ns=s.st_mtime_ns,ctime_ns=s.st_ctime_ns)
def reg(s):assert stat.S_ISREG(s['mode']) and s['links']==1
def sync(p,d=False):
 fd=os.open(p,os.O_RDONLY|(os.O_DIRECTORY if d else os.O_NOFOLLOW))
 try:os.fsync(fd)
 finally:os.close(fd)
def save(p,j):
 with p.open('x')as f:json.dump(j,f,indent=2);f.write('\n');f.flush();os.fsync(f.fileno())
 sync(p.parent,True)
def groups():
 z={str(p):p.read_text() for p in G.rglob('cgroup.procs')};assert all(not v.strip()for v in z.values()),z;return z
def child(name,argv):
 out=M/name;out.mkdir();save(out/'COMMAND.json',{'argv':argv,'close_fds':True,'wallSeconds':30});t=time.monotonic()
 with(out/'stdout.bin').open('xb')as so,(out/'stderr.bin').open('xb')as se:p=subprocess.run(argv,cwd=M,stdin=subprocess.DEVNULL,stdout=so,stderr=se,timeout=30,close_fds=True)
 save(out/'RESULT.json',{'actual_exit':p.returncode,'elapsed_seconds':time.monotonic()-t});assert p.returncode==0
def interrupted(s,f):raise InterruptedError('Root maintenance signal '+str(s))
for sig in(signal.SIGINT,signal.SIGTERM,signal.SIGHUP,signal.SIGQUIT,signal.SIGALRM):signal.signal(sig,interrupted)
signal.alarm(6200)
try:
 deadline=time.monotonic()+30
 for name in['.package-cache-mutate','.package-cache']:
  p=pathlib.Path('/home/charl/.cargo')/name;s=st(p);reg(s);fd=os.open(p,os.O_RDONLY|os.O_NOFOLLOW|os.O_CLOEXEC);fds.append(fd);fs=os.fstat(fd);assert(fs.st_dev,fs.st_ino)==(s['device'],s['inode'])
  while True:
   try:fcntl.flock(fd,fcntl.LOCK_EX|fcntl.LOCK_NB);break
   except BlockingIOError:
    if time.monotonic()>=deadline:raise TimeoutError('Cargo lock30s')
    time.sleep(.1)
  assert(st(p)['device'],st(p)['inode'])==(s['device'],s['inode']);identities.append(dict(path=str(p),**s))
 assert len({(s['device'],s['inode'])for s in identities})==2
 assert not list(source.iterdir()) and all(source.stat().st_dev!=s['device']for s in identities)
 assert not list((source.parent/'empty-home').iterdir())
 save(M/'PRELAUNCH-LOCKS-AND-INVARIANTS.json',{'locks':identities,'sourceDevice':source.stat().st_dev,'sourceEmpty':True,'groups':groups(),'holderPID':os.getpid(),'hostLockFDsNeverInherited':'Root operation subprocesses close_fds; later guard launched separately, no inheritance'})
 original=st(host);reg(original);assert original['size']==20024 and sha(host)==newsha
 assert recovered.stat().st_size==18266 and sha(recovered)==oldsha
 child('backup-copy',['/usr/bin/cp','--preserve=all','--no-clobber','--',str(host),str(backup)])
 assert backup.stat().st_size==20024 and sha(backup)==newsha;sync(backup);sync(M,True)
 save(M/'RESTORATION_OWED.json',{'originalPath':str(host),'originalLstat':original,'backupPath':str(backup),'backupSHA256':newsha,'recoveredSHA256':oldsha,'restorationOwed':True,'holderPID':os.getpid(),'locks':identities,'note':'Root holds both locks through fresh snapshot/admission/native terminal. Native guard not yet selected.'});armed=True
 assert(st(host)['device'],st(host)['inode'])==(original['device'],original['inode']) and sha(host)==newsha
 replaced=True
 child('replace-copy',['/usr/bin/cp','--no-preserve=mode,ownership,timestamps','--',str(recovered),str(host)])
 assert host.stat().st_size==18266 and sha(host)==oldsha;sync(host)
 for k in['device','inode','mode','uid','gid','links']:assert st(host)[k]==original[k]
 save(M/'REPLACED-EXACT-INDEX.json',{'lstat':st(host),'sha256':oldsha,'locksHeld':True})
 print('EXACT_HISTORICAL_INDEX_READY; bothCargoLocksHELD; RESTORATION_OWED; guardUNRUN. Send restore after guard terminal and empty groups.',flush=True)
 command=input()
 assert command=='restore','Expected literal restore'
except BaseException as e:
 save(M/'OPERATION-FAILURE.json',{'type':type(e).__name__,'message':str(e),'restorationOwed':armed});print('Maintenance interruption '+str(e),flush=True)
finally:
 signal.alarm(0)
 for sig in(signal.SIGINT,signal.SIGTERM,signal.SIGHUP,signal.SIGQUIT,signal.SIGALRM):signal.signal(sig,signal.SIG_IGN)
 if armed:
  try:
   gs=groups();s=st(host);reg(s);assert(s['device'],s['inode'])==(original['device'],original['inode']);assert backup.stat().st_size==20024 and sha(backup)==newsha;assert sha(host)==(oldsha if replaced else newsha)
   if replaced:child('restore-copy',['/usr/bin/cp','--preserve=all','--',str(backup),str(host)])
   assert host.stat().st_size==20024 and sha(host)==newsha;sync(host)
   s=st(host)
   if(s['uid'],s['gid'])!=(original['uid'],original['gid']):os.chown(host,original['uid'],original['gid'],follow_symlinks=False)
   os.chmod(host,stat.S_IMODE(original['mode']),follow_symlinks=False);os.utime(host,ns=(original['atime_ns'],original['mtime_ns']),follow_symlinks=False);final=st(host)
   for k in['device','inode','mode','uid','gid','links','size','atime_ns','mtime_ns']:assert final[k]==original[k],k
   save(M/'RESTORATION_COMPLETED.json',{'restorationOwed':False,'finalLstat':final,'shaVerifiedBeforeUtime':newsha,'finalCheck':'lstat only','ctimeChanged':final['ctime_ns']!=original['ctime_ns'],'groupsEmpty':gs});print('RESTORATION_COMPLETED original20024bytes/metadata; release locks; setup teardown stillowed',flush=True)
  except BaseException as e:
   save(M/'RECOVERY_REQUIRED.json',{'error':str(e),'restorationOwed':True,'locksHeldPID':os.getpid()});print('RECOVERY_REQUIRED locks retained, Root intervention needed',flush=True);input()
 elif original is not None:os.utime(host,ns=(original['atime_ns'],original['mtime_ns']),follow_symlinks=False)
 for fd in reversed(fds):fcntl.flock(fd,fcntl.LOCK_UN);os.close(fd)
